import {
  IObstacleDTO,
  IObstaclesForUserDTO,
  ObstacleCategoryDTO,
  ObstacleTypeDTO,
} from '../@types/obstacles.dto.types';
import {
  IObstacle,
  IObstacleForUser,
  ObstacleCategory,
  ObstacleType,
} from '../@types/obstacles.types';

export const mapObstacleTypeDTOToFront = (data: ObstacleTypeDTO): ObstacleType => {
  const map: Record<ObstacleTypeDTO, ObstacleType> = {
    pass: ObstacleType.Pass,
    peak: ObstacleType.Peak,
    poi: ObstacleType.Poi,
  };

  return map[data];
};

export const mapObstacleCategoryDTOToFront = (data: ObstacleCategoryDTO): ObstacleCategory => {
  const map: Record<ObstacleCategoryDTO, ObstacleCategory> = {
    ['no']: ObstacleCategory.CategoryNo,
    ['1a']: ObstacleCategory.Category1a,
    ['1b']: ObstacleCategory.Category1b,
    ['2a']: ObstacleCategory.Category2a,
    ['2b']: ObstacleCategory.Category2b,
    ['3a']: ObstacleCategory.Category3a,
    ['3b']: ObstacleCategory.Category3b,
    ['4a']: ObstacleCategory.Category4a,
    ['4b']: ObstacleCategory.Category4b,
    ['5a']: ObstacleCategory.Category5a,
    ['5b']: ObstacleCategory.Category5b,
    ['6a']: ObstacleCategory.Category6a,
    ['6b']: ObstacleCategory.Category6b,
  };

  return map[data];
};

export const mapObstacleDTOToFront = (data: IObstacleDTO): IObstacle => {
  return {
    id: +data.id,
    name: data.name,
    description: data.description,
    coordinates: [+data.lat, +data.lon],
    altitude: +data.altitude,
    link: data.link,
    comment: data.comment,
    type: mapObstacleTypeDTOToFront(data.type),
    category: mapObstacleCategoryDTOToFront(data.category),

    created: {
      date: new Date(data.created_at),
      id: +data.creator_id,
      name: data.creator_name,
    },

    updated:
      data.updator_id && data.updated_at && data.updator_id && data.updator_name
        ? {
            date: new Date(data.updated_at),
            id: +data.updator_id,
            name: data.updator_name,
          }
        : null,

    region: data.geo_region_id
      ? {
          id: +data.geo_region_id,
          name: data.geo_region_name,
        }
      : null,
  };
};

export const mapObstacleForUserDTOToFront = (backData: IObstaclesForUserDTO): IObstacleForUser => {
  return {
    ...mapObstacleDTOToFront(backData),
    id_hiking_obstacle: +backData.id_hiking_obstacle,
    date_in: new Date(backData.date_in),
    date_out: new Date(backData.date_out),
    hiking: {
      id: +backData.id_hiking,
      name: backData.hiking_name,
      ava: backData.hiking_ava,
      start: new Date(backData.hiking_start),
      finish: new Date(backData.hiking_finish),
    },
  };
};
